script:
"=== direct Zen API test ==="
$auth = Get-Content "$env:USERPROFILE\.local\share\opencode\auth.json" | ConvertFrom-Json
$token = $auth.opencode.key
"Token length: " + $token.Length
"Token prefix: " + $token.Substring(0, 10) + "..."
try {
  $headers = @{ "Authorization" = "Bearer $token"; "Content-Type" = "application/json" }
  $body = @{
    model = "space-bunny-free"
    messages = @(@{ role = "user"; content = "Say OK" })
    max_tokens = 10
  } | ConvertTo-Json -Depth 5
  $resp = Invoke-WebRequest -Uri "https://opencode.ai/zen/v1/chat/completions" -Method Post -Headers $headers -Body $body -TimeoutSec 30 -UseBasicParsing
  "Status: " + $resp.StatusCode
  ($resp.Content | ConvertFrom-Json).choices[0].message.content
} catch {
  "Failed: " + $_.Exception.Message
  if ($_.Exception.Response) {
    "Status: " + [int]$_.Exception.Response.StatusCode
  }
}
